import boto3

def extract_key_values_from_document(document_path):
    textract = boto3.client('textract')
    with open(document_path, 'rb') as file:
        document = file.read()
    response = textract.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['FORMS']
    )
    blocks = response['Blocks']
    key_map = {}
    value_map = {}
    block_map = {}
    for block in blocks:
        block_map[block['Id']] = block
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'KEY' in block['EntityTypes']:
                key_map[block['Id']] = block
            if 'VALUE' in block['EntityTypes']:
                value_map[block['Id']] = block
    def get_text(block_id, block_map):
        block = block_map[block_id]
        text = ''
        if 'Text' in block:
            text = block['Text']
        if 'Relationships' in block:
            for relationship in block['Relationships']:
                if relationship['Type'] == 'CHILD':
                    for child_id in relationship['Ids']:
                        text += get_text(child_id, block_map) + ' '
        return text.strip()
    kv_pairs = {}
    for key_id, key_block in key_map.items():
        if 'Relationships' in key_block:
            for relationship in key_block['Relationships']:
                if relationship['Type'] == 'VALUE':
                    for value_id in relationship['Ids']:
                        value_block = block_map.get(value_id)
                        if value_block:
                            key_text = get_text(key_id, block_map)
                            value_text = get_text(value_id, block_map)
                            kv_pairs[key_text] = value_text
                            break
                    break
    return kv_pairs
